  public function executeUpdate()
  {
    if (!$this->getRequestParameter('audit_log_id'))
    {
      $audit_log = new AuditLog();
    }
    else
    {
      $audit_log = AuditLogPeer::retrieveByPk($this->getRequestParameter('audit_log_id'));
      $this->forward404Unless($audit_log);
    }

    //$audit_log->setAuditLogId($this->getRequestParameter('audit_log_id'));
    $audit_log->setUsuarioId($this->getRequestParameter('usuario_id') ? $this->getRequestParameter('usuario_id') : null);
    $audit_log->setModuloId($this->getRequestParameter('modulo_id') ? $this->getRequestParameter('modulo_id') : null);
    $audit_log->setCampos($this->getRequestParameter('campos'));
    $audit_log->setValorAnterior($this->getRequestParameter('valor_anterior'));
    $audit_log->setValorNuevo($this->getRequestParameter('valor_nuevo'));
    if ($this->getRequestParameter('fecha_creacion'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_creacion'), $this->getUser()->getCulture());
      $audit_log->setFechaCreacion("$y-$m-$d");
    }
    $audit_log->setCodigoPrincipal($this->getRequestParameter('codigo_principal'));

    $audit_log->save();

    return $this->redirect($this->getRequest()->getScriptName().'/audit_log/show?audit_log_id='.$audit_log->getAuditLogId());
  }

  public function executeDelete()
